.evox-tagline { font-size: 15pt; font-weight: bold; color: #00A8B5; }
.evox-lock-bad { color: #d41f1f; font-weight: bold; }
.evox-subline { font-size: 11pt; opacity: 0.7; }
.evox-offline { background-image: none; background-color: #0060b3; color: #ffffff;
  border: 2px solid #cfe6ff; }
.evox-offline label { color: #ffffff; }
.evox-offline:disabled { opacity: 0.5; }
.evox-start-internet { background-image: none; background-color: #1FA855; color: #ffffff;
  border: 1px solid #d8f5e3; }
.evox-start-internet label { color: #ffffff; }
.evox-start-offline { background-image: none; background-color: #0060b3; color: #ffffff;
  border: 1px solid #cfe6ff; }
.evox-start-offline label { color: #ffffff; }
.evox-start-internet:disabled, .evox-start-offline:disabled { opacity: 0.5; }
.evox-cancel { background-image: none; background-color: #8B2A2A; color: #ffffff;
  border: 2px solid #f0d0d0; }
.evox-cancel label { color: #ffffff; }
.evox-danger { background-image: none; background-color: #d41f1f; color: #ffffff;
  border: 2px solid #ffd6d6; }
.evox-danger label { color: #ffffff; }
.evox-danger:disabled { opacity: 0.5; }
.evox-vault-btn { background-image: none; background-color: #D4AF37; color: #1a1400;
  border: 2px solid #fff1c2; }
.evox-vault-btn label { color: #1a1400; font-weight: bold; }
.evox-import-btn { background-image: none; background-color: #00F0FF; color: #001a1c;
  border: 2px solid #c8fcff; }
.evox-import-btn label { color: #001a1c; font-weight: bold; }
.evox-import-btn:disabled { opacity: 0.5; }
.evox-start-disposable { background-image: none; background-color: #39D353; color: #04210c;
  border: 2px solid #c9f7d3; }
.evox-start-disposable label { color: #04210c; font-weight: bold; }
.evox-start-disposable:disabled { opacity: 0.5; }
.evox-tabbtn { margin: 0; border-radius: 6px; }
.evox-tabbtn-vault:not(:checked) { background-color: rgba(212, 175, 55, 0.28); border: 2px solid rgba(212, 175, 55, 0.5); border-bottom: 3px solid rgba(212, 175, 55, 0.5); }
.evox-tabbtn-vault:not(:checked) label { color: mix(#D4AF37, @theme_fg_color, 0.35); }
.evox-tabbtn-vault:checked { border-bottom: 5px solid #fff1c2; }
.evox-tabbtn-template:not(:checked) { background-color: rgba(0, 240, 255, 0.28); border: 2px solid rgba(0, 240, 255, 0.5); border-bottom: 3px solid rgba(0, 240, 255, 0.5); }
.evox-tabbtn-template:not(:checked) label { color: mix(#00F0FF, @theme_fg_color, 0.35); }
.evox-tabbtn-template:checked { border-bottom: 5px solid #c8fcff; }
.evox-tabbtn-disposable:not(:checked) { background-color: rgba(57, 211, 83, 0.28); border: 2px solid rgba(57, 211, 83, 0.5); border-bottom: 3px solid rgba(57, 211, 83, 0.5); }
.evox-tabbtn-disposable:not(:checked) label { color: mix(#39D353, @theme_fg_color, 0.35); }
.evox-tabbtn-disposable:checked { border-bottom: 5px solid #c9f7d3; }
.evox-howto { padding: 4px 8px; min-height: 24px; font-weight: bold; }
.evox-howto-compact { min-height: 18px; }
.evox-howto:disabled { opacity: 0.45; }
.evox-howto-orange { background-image: none; background-color: #E0802A; color: #1f0f00;
  border: 2px solid #ffd9b3; }
.evox-howto-orange label { color: #1f0f00; font-weight: bold; }
.evox-next { box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.9), 0 0 8px 3px rgba(255, 255, 255, 0.55); }
.evox-next.evox-start-disposable { box-shadow: 0 0 0 2px #9BF5AE, 0 0 10px 3px #39D353; }
.evox-next.evox-start-offline { box-shadow: 0 0 0 2px #4DA3FF, 0 0 10px 3px #0060b3; }
.evox-block { border: 1px solid alpha(@theme_fg_color, 0.25); border-radius: 4px; padding: 4px 8px; }
.evox-block-title { font-weight: bold; color: #00A8B5; }
.evox-block-small { font-size: 11pt; opacity: 0.8; }
.evox-mon-block .evox-block-title { font-size: 13pt; }
.evox-big { font-size: 20pt; font-weight: bold; }
.evox-mid { font-size: 14pt; font-weight: bold; }
.evox-details-btn { font-weight: bold; padding-top: 4px; padding-bottom: 4px; }
.evox-mon-head { font-size: 16pt; font-weight: bold; color: #39D353; }
.evox-mon-num { font-size: 22pt; font-weight: bold; }
.evox-mon-stopped { font-size: 40pt; font-weight: bold; opacity: 0.85; }
.evox-ram-hint { font-weight: bold; }
.evox-howto-title { font-weight: bold; opacity: 0.8; }
.evox-flash { box-shadow: 0 0 0 3px #ffffff, 0 0 14px 6px #ffd400; }
.evox-vault-hint { color: #D4AF37; font-weight: bold; }
.evox-novault-hint { background-color: #D4AF37; color: #1a1400; border-radius: 4px; padding: 4px 8px;
  font-size: 12pt; font-weight: bold; }
treeview.view:selected { background-color: #E0A030; background-image: none; color: #1a1000; }
treeview.view:selected:focus { background-color: #E0A030; background-image: none; color: #1a1000; }
treeview.view:selected:hover { background-color: #E0A030; background-image: none; color: #1a1000; }
treeview.view:selected:backdrop { background-color: #E0A030; background-image: none; color: #1a1000; }
list row:selected { background-color: #E0A030; background-image: none; color: #1a1000; }
list row:selected:focus { background-color: #E0A030; background-image: none; color: #1a1000; }
list row:selected:hover { background-color: #E0A030; background-image: none; color: #1a1000; }
list row:selected:backdrop { background-color: #E0A030; background-image: none; color: #1a1000; }
treeview.view:hover { background-color: alpha(#E0A030, 0.25); }
treeview.view.evox-sel-teal:hover { background-color: alpha(#00F0FF, 0.25); }
treeview.view.evox-sel-teal:selected { background-color: #00F0FF; background-image: none; color: #001a1c; }
treeview.view.evox-sel-teal:selected:focus { background-color: #00F0FF; background-image: none; color: #001a1c; }
treeview.view.evox-sel-teal:selected:hover { background-color: #00F0FF; background-image: none; color: #001a1c; }
treeview.view.evox-sel-teal:selected:backdrop { background-color: #00F0FF; background-image: none; color: #001a1c; }
treeview.view.evox-sel-green:hover { background-color: alpha(#39D353, 0.25); }
treeview.view.evox-sel-green:selected { background-color: #39D353; background-image: none; color: #04210c; }
treeview.view.evox-sel-green:selected:focus { background-color: #39D353; background-image: none; color: #04210c; }
treeview.view.evox-sel-green:selected:hover { background-color: #39D353; background-image: none; color: #04210c; }
treeview.view.evox-sel-green:selected:backdrop { background-color: #39D353; background-image: none; color: #04210c; }
.evox-warn { color: #d41f1f; font-weight: bold; }
.evox-btn-sub { font-size: 10pt; font-weight: normal; }
.evox-bar-internet { background-color: #1FA855; }
.evox-bar-offline { background-color: #0060b3; }
.evox-chip { background-image: none; padding: 1px 6px; min-height: 0; min-width: 0; font-weight: bold;
  border-radius: 4px; }
.evox-grp { font-weight: bold; padding: 0 2px; }
.evox-grp-everyday { color: mix(#4C8DFF, @theme_fg_color, 0.3); border-bottom: 2px solid #4C8DFF; }
.evox-chip-everyday { color: mix(#4C8DFF, @theme_fg_color, 0.3); border: 1px solid #4C8DFF; background-color: rgba(76, 141, 255, 0.16); }
.evox-chip-everyday:hover { background-color: rgba(76, 141, 255, 0.32); }
.evox-grp-money { color: mix(#E0A030, @theme_fg_color, 0.3); border-bottom: 2px solid #E0A030; }
.evox-chip-money { color: mix(#E0A030, @theme_fg_color, 0.3); border: 1px solid #E0A030; background-color: rgba(224, 160, 48, 0.16); }
.evox-chip-money:hover { background-color: rgba(224, 160, 48, 0.32); }
.evox-grp-work { color: mix(#2BB3A3, @theme_fg_color, 0.3); border-bottom: 2px solid #2BB3A3; }
.evox-chip-work { color: mix(#2BB3A3, @theme_fg_color, 0.3); border: 1px solid #2BB3A3; background-color: rgba(43, 179, 163, 0.16); }
.evox-chip-work:hover { background-color: rgba(43, 179, 163, 0.32); }
.evox-grp-more { color: mix(#9AA4B2, @theme_fg_color, 0.3); border-bottom: 2px solid #9AA4B2; }
.evox-chip-more { color: mix(#9AA4B2, @theme_fg_color, 0.3); border: 1px solid #9AA4B2; background-color: rgba(154, 164, 178, 0.16); }
.evox-chip-more:hover { background-color: rgba(154, 164, 178, 0.32); }
.evox-grp-mylist { color: mix(#E07AA8, @theme_fg_color, 0.3); border-bottom: 2px solid #E07AA8; }
.evox-chip-mylist { color: mix(#E07AA8, @theme_fg_color, 0.3); border: 1px solid #E07AA8; background-color: rgba(224, 122, 168, 0.16); }
.evox-chip-mylist:hover { background-color: rgba(224, 122, 168, 0.32); }
.evox-fn-make { background-image: none; background-color: #C06010; color: #1f0f00; border: 2px solid #ffd9b3; }
.evox-fn-make label { color: #1f0f00; font-weight: bold; }
.evox-fn-make:disabled { background-color: rgba(192, 96, 16, 0.28); color: mix(#C06010, @theme_fg_color, 0.35); border: 2px solid rgba(192, 96, 16, 0.5); }
.evox-fn-make:disabled label { color: mix(#C06010, @theme_fg_color, 0.35); }
.evox-fn-verify { background-image: none; background-color: #4A6F94; color: #ffffff; border: 2px solid #dbe6f1; }
.evox-fn-verify label { color: #ffffff; font-weight: bold; }
.evox-fn-verify:disabled { background-color: rgba(74, 111, 148, 0.28); color: mix(#4A6F94, @theme_fg_color, 0.35); border: 2px solid rgba(74, 111, 148, 0.5); }
.evox-fn-verify:disabled label { color: mix(#4A6F94, @theme_fg_color, 0.35); }
.evox-fn-remove { background-image: none; background-color: #9A4A4A; color: #ffffff; border: 2px solid #f0d9d9; }
.evox-fn-remove label { color: #ffffff; font-weight: bold; }
.evox-fn-remove:disabled { background-color: rgba(154, 74, 74, 0.28); color: mix(#9A4A4A, @theme_fg_color, 0.35); border: 2px solid rgba(154, 74, 74, 0.5); }
.evox-fn-remove:disabled label { color: mix(#9A4A4A, @theme_fg_color, 0.35); }
.evox-fn-exit { background-image: none; background-color: #8B2A2A; color: #ffffff; border: 2px solid #f0d0d0; }
.evox-fn-exit label { color: #ffffff; font-weight: bold; }
.evox-fn-exit:disabled { background-color: rgba(139, 42, 42, 0.28); color: mix(#8B2A2A, @theme_fg_color, 0.35); border: 2px solid rgba(139, 42, 42, 0.5); }
.evox-fn-exit:disabled label { color: mix(#8B2A2A, @theme_fg_color, 0.35); }
.evox-fn-neutral { background-image: none; background-color: #4F6A86; color: #ffffff; border: 2px solid #d6e0eb; }
.evox-fn-neutral label { color: #ffffff; font-weight: bold; }
.evox-fn-neutral:disabled { background-color: rgba(79, 106, 134, 0.28); color: mix(#4F6A86, @theme_fg_color, 0.35); border: 2px solid rgba(79, 106, 134, 0.5); }
.evox-fn-neutral:disabled label { color: mix(#4F6A86, @theme_fg_color, 0.35); }
.evox-fn-aux { background-image: none; background-color: #6A6F94; color: #ffffff; border: 2px solid #dcdeee; }
.evox-fn-aux label { color: #ffffff; font-weight: bold; }
.evox-fn-aux:disabled { background-color: rgba(106, 111, 148, 0.28); color: mix(#6A6F94, @theme_fg_color, 0.35); border: 2px solid rgba(106, 111, 148, 0.5); }
.evox-fn-aux:disabled label { color: mix(#6A6F94, @theme_fg_color, 0.35); }

button:focus, radiobutton:focus, checkbutton:focus, .evox-tabbtn:focus, .evox-chip:focus, .evox-howto:focus, entry:focus, spinbutton:focus, combobox:focus, list row:focus, expander:focus
  { outline-color: #C6FF00; outline-style: solid; outline-width: 4px;
    outline-offset: -4px; box-shadow: inset 0 0 0 6px #0A0A0F, 0 0 8px 2px alpha(#C6FF00, 0.65); }
/* 0.6.19: kein Rahmen je Zelle; ein Rahmen um das ganze Listenfeld (Wrapper .evox-listframe, Rand immer gleich dick, nur transparent -> kein Sprung) */
treeview.view.cell:focus { outline-style: none; box-shadow: none; }
.evox-listframe { border: 4px solid transparent; padding: 2px; }
.evox-listframe.evox-listfocus { border-color: #C6FF00; box-shadow: inset 0 0 0 2px #0A0A0F, 0 0 8px 2px alpha(#C6FF00, 0.65); }
.evox-next:focus { box-shadow: inset 0 0 0 6px #0A0A0F, 0 0 0 2px rgba(255, 255, 255, 0.9), 0 0 8px 2px alpha(#C6FF00, 0.65); }
.evox-next.evox-start-disposable:focus { box-shadow: inset 0 0 0 6px #0A0A0F, 0 0 0 2px #9BF5AE, 0 0 8px 2px alpha(#C6FF00, 0.65); }
.evox-next.evox-start-offline:focus { box-shadow: inset 0 0 0 6px #0A0A0F, 0 0 0 2px #4DA3FF, 0 0 8px 2px alpha(#C6FF00, 0.65); }
.evox-focusline { font-size: 11pt; padding: 3px 8px; border-top: 1px solid alpha(@theme_fg_color, 0.35);
  background-color: alpha(@theme_fg_color, 0.07); }

.evox-hint-bar { background-color: #D4AF37; border-radius: 4px; padding: 4px 8px; }
.evox-hint-bar label { color: #1a1400; }
.evox-hint-icon { font-size: 16pt; font-weight: bold; }
.evox-hint-text { font-size: 12pt; }
.evox-hint-close { background-image: none; background-color: transparent; color: #1a1400;
  border: 1px solid #1a1400; padding: 0 6px; min-height: 0; min-width: 0; }
.evox-hint-close label { color: #1a1400; font-weight: bold; }
.evox-vmname { font-size: 26pt; font-weight: bold; color: #39D353; }
.evox-dlg-internet { border: 1px solid #1FA855; }
.evox-dlg-offline { border: 1px solid #0060b3; }
.evox-bar-expl { font-size: 11pt; color: #ffffff; }
.evox-bar-icon { font-size: 24pt; color: #ffffff; }
.evox-bar-text { font-size: 20pt; font-weight: bold; color: #ffffff; }
